        "Release workflow must target Linux x64"
    );
    assert!(
        workflow.contains("aarch64-apple-darwin"),
        "Release workflow must target macOS ARM64"
    );
    assert!(
        workflow.contains("x86_64-pc-windows-msvc"),
        "Release workflow must target Windows x64"
    );
}

